import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Kanban Work","description":"","frontmatter":{},"headers":[],"relativePath":"demo/kanban.md","filePath":"demo/kanban.md"}'),o={name:"demo/kanban.md"};function n(s,e,d,l,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="kanban-work" tabindex="-1">Kanban Work <a class="header-anchor" href="#kanban-work" aria-label="Permalink to &quot;Kanban Work&quot;">​</a></h1><p>The first demo is a Kanban workspace: a board application, its data, an application Service, and a Harness that helps build and operate it. It illustrates how the whole runnable workspace can be shared and continued.</p><div class="info custom-block"><p class="custom-block-title">Demo status</p><p>A public Kanban <code>.work</code> archive, recording, and screenshots are not available yet. This page describes the demo structure and how to build or import a board with the current product. It does not claim that a prebuilt demo has been released.</p></div><h2 id="what-is-inside" tabindex="-1">What is inside? <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to &quot;What is inside?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Role in the demo</th></tr></thead><tbody><tr><td>Workspace</td><td>Application source and board data in managed storage.</td></tr><tr><td>Service</td><td>A container running the board&#39;s web UI and API.</td></tr><tr><td>Harness</td><td>Models, tools, instructions, and history used to build and operate the board.</td></tr><tr><td>Configuration</td><td>The image, command, declared HTTP port, workspace mount, and readiness check.</td></tr></tbody></table><p>One application Service is sufficient for a first board. A separate database Service is optional; the actual implementation determines which Services are present. Inspect the Service list rather than assuming a fixed stack.</p><h2 id="build-a-board-in-piwork" tabindex="-1">Build a board in Piwork <a class="header-anchor" href="#build-a-board-in-piwork" aria-label="Permalink to &quot;Build a board in Piwork&quot;">​</a></h2><p><a href="/piwork/guide/installation.html">Install Piwork</a>, open Desktop, and create and start a Work named <code>Kanban</code>. In Chat, you can ask:</p><blockquote><p>Build a small Kanban board in the shared workspace with Todo, Doing, and Done columns. Persist its data in the managed workspace. Declare the application as a Service using the available Work Service tools, with an HTTP port and readiness check. Inspect the running Service and tell me what you verified.</p></blockquote><p>This is an example task for the Harness. Its result depends on the model and environment; it is not an installation command or a validated downloadable demo.</p><p>Open the Service in Desktop. Add a card, move it, and reload the application. Check that the data persists. Inspect application files through <strong>Files</strong>.</p><h2 id="what-the-harness-does" tabindex="-1">What the Harness does <a class="header-anchor" href="#what-the-harness-does" aria-label="Permalink to &quot;What the Harness does&quot;">​</a></h2><p>The Harness can inspect the workspace, write the application, declare the Service, read logs, and verify its running state. Later, ask it to change the board and check the result.</p><p>A board that implements the experimental brain&#39;s capability contract can also expose structured board queries and actions. That integration needs application code; ordinary HTTP access does not provide it automatically. See <a href="/piwork/spec/harness.html">Harness Spec</a>.</p><h2 id="demonstrate-portability" tabindex="-1">Demonstrate portability <a class="header-anchor" href="#demonstrate-portability" aria-label="Permalink to &quot;Demonstrate portability&quot;">​</a></h2><ol><li>Create a card with a recognizable title and confirm it persists.</li><li>Stop the Work and export it.</li><li>Save and inspect the <code>.work</code> file.</li><li>Import it into a compatible second Core with its own model configuration.</li><li>Start the imported Work and open its board Service.</li><li>Confirm the card and files are present, then continue changing the board.</li></ol><p>The exact commands are in <a href="/piwork/guide/first-work.html">Your First Work</a>. They also work for an archive supplied by a trusted demo publisher. Use the ID returned by import; it identifies a new Work.</p><h2 id="demo-materials" tabindex="-1">Demo materials <a class="header-anchor" href="#demo-materials" aria-label="Permalink to &quot;Demo materials&quot;">​</a></h2><p>The recording, screenshots, and archive link will be added here when they are published. For now, <a href="https://github.com/pphboy/piwork/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> is the place to share a reproducible board or report a problem.</p>',19)])])}const m=a(o,[["render",n]]);export{b as __pageData,m as default};
